{
  "families": [
    {
      "family": "iterative",
      "ranges": [
        {"param": "data_width", "low": 10, "high": 18, "choices": null},
        {"param": "n_iter", "low": 8, "high": 18, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
      ],
      "budget_share": 0.7,
      "why": "Smallest datapath: one shared adder/shifter chain reused over N+3 cycles. With N up to 18, the throughput floor of 1 MSPS only requires roughly 21 MHz, which is easily met on Artix-7. Search modest W and N to find the minimum LUT+FF design that still satisfies max_abs_err <= 2^-10; guards and rounding are included because they affect accuracy without changing the datapath size much."
    },
    {
      "family": "unrolled_k",
      "ranges": [
        {"param": "data_width", "low": 10, "high": 18, "choices": null},
        {"param": "n_iter", "low": 8, "high": 18, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
        {"param": "k", "low": 2, "high": 4, "choices": null}
      ],
      "budget_share": 0.3,
      "why": "Shares the same accuracy model as iterative, but k chained micro-rotations per cycle reduce the cycle count at the cost of k-1 extra adders/shifters. With k=2..4 the area increase is modest, and it may provide a different area/throughput point if iterative's Fmax were limiting. Given the low 1 MSPS floor, it is likely dominated by iterative on area, so a smaller share is used to confirm and to catch any unexpected corner."
    }
  ],
  "rationale": "The spec is area-critical with a low throughput floor (1 MSPS) and moderate accuracy (2^-10). Shared-datapath families (iterative, unrolled_k) reuse one adder/shifter chain and therefore have the smallest area; pipelined families replicate the datapath per stage and are expected to be dominated on the LUT+FF objective. Accuracy depends only on data_width, n_iter, angle_guard, frac_guard and rounding, so these are searched jointly. Ranges are kept modest to target the area-accuracy knee but wide enough to cover the feasible region: W 10..18 and N 8..18 should span from just below to comfortably above the 2^-10 error requirement. Most budget goes to iterative because it has the smallest datapath and can easily meet 1 MSPS at these N values; unrolled_k gets a smaller share to check whether a small k can improve Fmax enough to matter without adding too much area."
}

{
  "decision": "map_front",
  "next_plan": null,
  "rationale": "The Pareto front is entirely `iterative` and only occupies luts_plus_ffs 269..404 of the 1500 area reference and data_width 16..18 of the registry's 8..28 — a small part of both objective ranges. Decomposing HV over my own front (recomputing the 2-D dominated area with the last point's rectangle reaching the ref at 1500) shows the segment from the highest-accuracy point (404 area, 14.04 bits) out to the ref contributes ~4400 of the reported 4795, i.e. the HV is almost entirely set by how far accuracy extends while area stays well under 1500. So the dominant remaining lever is sweeping data_width/n_iter upward (accuracy is family-independent; only n_iter/data_width/guards/rounding set it) to fill the 404..1500 area band with higher-accuracy points, not squeezing the already-known 269-area corner (that corner already exists and is what the selection rule picks, and 0% of evals violate throughput, so throughput is not the risk). Hence spend this round letting NSGA-II map the full ranges of the family on the front, seeded with the current front. The two unexplored families are not HV candidates: their accuracy is identical by construction, and the only family that reaches the front is the cheapest one at a given accuracy — unrolled_k (k=4, i.e. only 4× replication) already costs 483 vs iterative's 269 at similar accuracy, so pipelined/pipelined_m (even more replicated datapaths) cannot supply new non-dominated points and would only burn budget that should go to extending the accuracy axis."
}

{
  "decision": "add_family",
  "rationale": "Round 2/4, 200/400 evals used. The feasible front is entirely from iterative + unrolled_k; the two registered families (pipelined, pipelined_m) are unexplored. The spec's binding objective is min luts_plus_ffs and its only hard constraint is throughput >= 1 MSPS, which iterative already clears by ~11x (best seen 18.5 MSPS), so throughput is not the lever. However, the front's area span is only 257..626 against an HV reference of 1500, and the front is built from shared-datapath/barrel-shifter designs. pipelined_m with a large m (register every m stages) replaces the shared barrel shifters with constant-shift stages and 1 result/cycle, so its luts_plus_ffs could be competitive at the low-area corner while adding new (area, accuracy) points that raise hypervolume. Worth one round before the reserved front-mapping round.",
  "next_plan": {
    "families": [
      {
        "family": "pipelined_m",
        "ranges": [
          {"param": "data_width", "low": 14, "high": 28, "choices": null},
          {"param": "n_iter", "low": 12, "high": 30, "choices": null},
          {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
          {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
          {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
          {"param": "m", "low": 4, "high": 8, "choices": null}
        ]
     ,  "budget_share": 0.6
      ,  "why": "large m keeps FF count down while giving 1 result/cycle; constant shifts may beat shared barrel shifters on LUTs at the low-area corner (target luts_plus_ffs near 257)."
      },
      {
        "family": "pipelined",
        "ranges": [
          {"param": "data_width", "low": 14, "high": 24, "choices": null},
          {"param": "n_iter", "low": 12, "high": 24, "choices": null},
          {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
          {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
          {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
        ]
      ,  "budget_share": 0.4
      ,  "why": "full per-stage registration is the area-worst case but bounds the family; needed to know whether any pipelined point is non-dominated."
      }
    ],
    "rationale": "seed with the current 28-design front; keep the low-area corner (luts_plus_ffs <= 400) densely sampled since the selection rule is min luts_plus_ffs, and let the rest of the budget probe higher-accuracy/higher-area points to extend the front toward the 1500 area reference."
  }
}

{
  "rationale": "Round 3 produced 0.0% hypervolume gain, so the front has stabilised, but 100 evaluations remain and this is the final round. The front already spans all four families (iterative, unrolled_k, pipelined, pipelined_m) and covers luts_plus_ffs 257..3081 with accuracy_bits 10.3..23.7, yet the high-accuracy end (pipelined_m at 3081) lies beyond the HV reference of 1500 and the low-area end (iterative at 257) is the selection target. The reserved final-round budget is best spent mapping the full ranges of the families already on the front, seeded with the current Pareto set, to confirm there are no gaps in the trade-off curve and to finalise the front before selection. No further narrowing is justified given the 0% gain.",
  "next_plan": null,
  "decision": "map_front"
}
